theorem extracted_1.{u_5, u_4, u_3, u_2, u_1} {G : Type u_1} [inst : AddCommGroup G] [inst_1 : Fintype G]
  [hG : MeasurableSpace G] [inst_2 : MeasurableSingletonClass G] {Ω₀₁ : Type u_2} {Ω₀₂ : Type u_3}
  [inst_3 : MeasureSpace Ω₀₁] [inst_4 : MeasureSpace Ω₀₂] {p : refPackage Ω₀₁ Ω₀₂ G} {Ω : Type u_4}
  [inst_5 : MeasureSpace Ω] {X₁ X₂ : Ω → G} (h_min : tau_minimizes p X₁ X₂) {Ω' : Type u_5} [inst_6 : MeasureSpace Ω']
  [inst_7 : IsProbabilityMeasure ℙ] {T₁ T₂ T₃ : Ω' → G} (hT : T₁ + T₂ + T₃ = 0) (hT₁ : Measurable T₁)
  (hT₂ : Measurable T₂) (hT₃ : Measurable T₃) :
  let sum1 := ∫ (x : G), (fun t => d[T₁ ; ℙ[|T₃ ⁻¹' {t}] # T₂ ; ℙ[|T₃ ⁻¹' {t}]]) x ∂Measure.map T₃ ℙ;
  let sum2 := ∫ (x : G), (fun t => d[p.X₀₁ ; ℙ # T₁ ; ℙ[|T₃ ⁻¹' {t}]] - d[p.X₀₁ # X₁]) x ∂Measure.map T₃ ℙ;
  let sum3 := ∫ (x : G), (fun t => d[p.X₀₂ ; ℙ # T₂ ; ℙ[|T₃ ⁻¹' {t}]] - d[p.X₀₂ # X₂]) x ∂Measure.map T₃ ℙ;
  let sum4 := ∫ (x : G), (fun t => ψ[T₁; ℙ[|T₃ ⁻¹' {t}] # T₂ ; ℙ[|T₃ ⁻¹' {t}]]) x ∂Measure.map T₃ ℙ;
  T₃ = T₁ + T₂ →
    IsProbabilityMeasure (Measure.map T₃ ℙ) →
      sum1 ≤ δ →
        sum2 = d[p.X₀₁ # T₁ | T₃] - d[p.X₀₁ # X₁] →
          sum3 = d[p.X₀₂ # T₂ | T₃] - d[p.X₀₂ # X₂] → sum4 ≤ δ + p.η * c[T₁ | T₃ # T₂ | T₃] → k ≤ sum4 := by
  subst h2T₃; exact ent_bsg hT₁ hT₂

theorem extracted_1.{u_5, u_4, u_3, u_2, u_1} {G : Type u_1} [inst : AddCommGroup G] [inst_1 : Fintype G]
  [hG : MeasurableSpace G] [inst_2 : MeasurableSingletonClass G] {Ω₀₁ : Type u_2} {Ω₀₂ : Type u_3}
  [inst_3 : MeasureSpace Ω₀₁] [inst_4 : MeasureSpace Ω₀₂] {p : refPackage Ω₀₁ Ω₀₂ G} {Ω : Type u_4}
  [inst_5 : MeasureSpace Ω] {X₁ X₂ : Ω → G} (h_min : tau_minimizes p X₁ X₂) {Ω' : Type u_5} [inst_6 : MeasureSpace Ω']
  [inst_7 : IsProbabilityMeasure ℙ] {T₁ T₂ T₃ : Ω' → G} (hT : T₁ + T₂ + T₃ = 0) (hT₁ : Measurable T₁)
  (hT₂ : Measurable T₂) (hT₃ : Measurable T₃) :
  let sum1 := ∫ (x : G), (fun t => d[T₁ ; ℙ[|T₃ ⁻¹' {t}] # T₂ ; ℙ[|T₃ ⁻¹' {t}]]) x ∂Measure.map T₃ ℙ;
  T₃ = T₁ + T₂ → IsProbabilityMeasure (Measure.map T₃ ℙ) → sum1 ≤ δ → k ≤ δ + p.η * c[T₁ | T₃ # T₂ | T₃] := by
  add_sub_cancel_right]

