theorem extracted_1.{u_1} {G : Type u_1} [inst : AddCommGroup G] [inst_1 : Module (ZMod 2) G] {A : Set G} {K : ℝ}
  (h₀A : A.Nonempty) (hA : ↑(Nat.card ↑(A + A)) ≤ K * ↑(Nat.card ↑A)) (A_fin : Finite ↑A) :
  let mG := ⊤;
  MeasurableSingletonClass G →
    0 < ↑(Nat.card ↑A) →
      0 < K →
        let A' := ⋯.toFinset;
        A'.Nonempty := by
  simp [A', Finset.Nonempty]
      exact h₀A

theorem extracted_1.{u_1} {G : Type u_1} [inst : AddCommGroup G] [inst_1 : Module (ZMod 2) G] {A : Set G} {K : ℝ}
  (h₀A : A.Nonempty) (hA : ↑(Nat.card ↑(A + A)) ≤ K * ↑(Nat.card ↑A)) : Finite ↑A := by
  infer_instance

theorem extracted_1.{u_3} {G : Type u_3} [inst : AddCommGroup G] [inst_1 : Module (ZMod 2) G] {A : Set G} {K : ℝ}
  (h₀A : A.Nonempty) (Afin : A.Finite) (hA : ↑(Nat.card ↑(A + A)) ≤ K * ↑(Nat.card ↑A)) :
  let G' := Submodule.span (ZMod 2) A;
  let ι := G'.subtype;
  Injective ⇑ι → A ⊆ range ⇑ι := by
  simp only [AddMonoidHom.coe_coe, Submodule.coe_subtype, Subtype.range_coe_subtype, G', ι]
      exact Submodule.subset_span

/-- Version of `distance_ge_of_min` with the measures made explicit. -/
lemma distance_ge_of_min' {Ω'₁ Ω'₂ : Type*} (h : tau_minimizes p X₁ X₂)
    [MeasurableSpace Ω'₁] [MeasurableSpace Ω'₂] {μ : Measure Ω'₁} {μ' : Measure Ω'₂}
    [IsProbabilityMeasure μ] [IsProbabilityMeasure μ'] {X₁': Ω'₁ → G} {X₂': Ω'₂ → G}
    (h1 : Measurable X₁') (h2 : Measurable X₂') :
    d[X₁ # X₂] - p.η * (d[p.X₀₁; ℙ # X₁'; μ] - d[p.X₀₁ # X₁])
      - p.η * (d[p.X₀₂; ℙ # X₂'; μ'] - d[p.X₀₂ # X₂]) ≤ d[X₁'; μ # X₂'; μ'] := by
  set M1 : MeasureSpace Ω'₁ := { volume := μ }
  set M2 : MeasureSpace Ω'₂ := { volume := μ' }
  exact distance_ge_of_min p h h1 h2

